import math

def special_factorial(n):
    def factorial(num):
        if num == 0:
            return 1
        return math.factorial(num)

    result = 1
    for i in range(1, n+1):
        result *= factorial(i)

    return result

# Test the function
print(special_factorial(4))  # Output should be 288

